import asyncio
from app.collectors.website import WebsiteCollector

URL = "https://news.google.?oc=5"

async def main():
    c=WebsiteCollector()
    print('is_wrapper', c._is_google_news_wrapper(URL))
    resolved=await c._resolve_google_wrapper_url_with_playwright(URL)
    print('resolved=',resolved)

asyncio.run(main())
